THEMES = ["Bruit / vibrations", "Meule cassée ou fissurée", "Usure irrégulière", "Mauvaise qualité de coupe",
          "Problème d'arrosage", "Réglage / machine", "Fiche du monteur incomplète ou illisible", "Autre"]
SEUIL_NON_FINIE_MM = Decimal("2")


def themes_et_marques_x(apps, schema_editor):
    """Crée les thèmes d'origine et pose la marque X sur les meules déjà démontées (seuil d'origine : 2 mm)."""
    ThemeProbleme = apps.get_model("remontees", "ThemeProbleme")
    SaisieMeule = apps.get_model("remontees", "SaisieMeule")
    for ordre, libelle in enumerate(THEMES):
        ThemeProbleme.objects.get_or_create(libelle=libelle, defaults={"ordre": ordre})
    SaisieMeule.objects.filter(hauteur_finale__gt=SEUIL_NON_FINIE_MM).update(non_finie=True)


